use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},fmt::Write};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-opposite-scalar-census");let pins: BTreeMap<String,String>=serde_json::from_value(read(r.join("input-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h,"{p}");}assert_eq!(read(r.join("run/result.json"))["status"],"complete");for step in ["link","census"]{let d=r.join("run").join(step);let e=read(d.join("exit.json"));assert_eq!(e["success"],true);for stream in ["stdout","stderr"]{assert_eq!(hash(d.join(format!("{stream}.log"))),e[format!("{stream}_sha256")].as_str().unwrap());}}
 let out=fs::read_to_string(r.join("run/census/stdout.log")).unwrap();let rows=out.lines().filter_map(|l|l.strip_prefix("ROW ")).map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>();assert_eq!(rows.len(),27);let mut keys=BTreeSet::new();let mut checks=0;let mut max=0f64;for row in &rows{assert!(keys.insert((row["shape"].as_str().unwrap(),row["query"].as_str().unwrap())));assert_eq!(row["raw_and_solver_image_solutions_equal"],true);let s=&row["stats"];assert_eq!(s["independent_weighted_field_checks"],2);checks+=s["per_scalar_integer_and_sign_checks"].as_u64().unwrap();if row["query"]!="rawK_diagnostic"{max=max.max(s["unique_class_reduction_fraction"].as_f64().unwrap());}}
 assert!(out.lines().last().unwrap().starts_with("COMPLETE "));let result=json!({"status":"closed_verified","rows":rows,"pins_rehashed":pins.len(),"raw_vs_image_vector_agreement_cases":9,"explicit_scalar_solves":18,"queries":27,"per_scalar_integer_and_sign_checks":checks,"query_weighted_field_checks":54,"synthetic_weighted_field_checks":2,"max_A_B_unique_class_reduction_fraction":max,"new_sdk_proofs":0,"new_gnark_exports":0,"adopted":false,"accepted_170_sources_unchanged":true,"decision":"Do not implement opposite-scalar grouping for the speed goal: observed incremental class reduction is tiny; no latency gain is claimed or mathematically ruled out for other inputs.","next":"Separately freeze modal scalar-translation population census: compare occurrence frequencies, not only unique classes. With key-only S=sum(P), use sum(sP)=cS+sum((s-c)P); skip most frequent scalar instead of zero. Need exact regrouping, setup/memory costs and actual caller/fullSDK qualification if opportunity exists."});fs::write(r.join("results.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();
 let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-opposite-scalar-census");fs::create_dir(report).unwrap();let mut s=String::from("# Opposite-scalar grouping opportunity\n\nFresh accepted-library scalar solves show little additional grouping opportunity from opposite values. Primary A removes one class out of 17,454; primary B removes three out of 26,142. The largest A/B class reduction across nine fixtures is below 0.08%. No curve implementation or performance trial follows from this census. Production is unchanged.\n\nCurrent grouping merges equal nonzero scalars. This read-only census also groups x with -x, independently computes canonical integer p-x, checks field negation and sign reconstruction, and validates two deterministic weighted field linear functionals per vector. A signed base sum would require extra point formation before windowing, so class reductions are not free point-operation savings or predicted latency.\n\n| Shape | Query | Positions | Equal nonzero classes | Sign classes | Extra class reduction % |\n| --- | --- | ---: | ---: | ---: | ---: |\n");for row in result["rows"].as_array().unwrap(){let t=&row["stats"];writeln!(s,"| {} | {} | {} | {} | {} | {:.6} |",row["shape"].as_str().unwrap(),row["query"].as_str().unwrap(),t["positions"],t["nonzero_equality_classes"],t["signed_classes"],t["unique_class_reduction_fraction"].as_f64().unwrap()*100.).unwrap();}
 writeln!(s,"\nAll 27 vectors pass 54 weighted field checks and {checks} integer/sign checks. Nine raw/cached-image output-vector comparisons agree, from 18 explicit public scalar solves. Synthetic zero, cancellation, duplicates and 128 random opposite pairs also pass. All 202 source/library/key/fixture pins and workflow receipts match after execution. No witness, private scalar, point or proof arrays are exported.\n").unwrap();s.push_str("Raw K is diagnostic: it is not the accepted folded K/Euler H hot path. A/B scalars use the accepted solver, but this census models exact equality classes rather than reproducing every grouping sampling/admission choice. One established fixture per shape cannot prove absence of opportunity for arbitrary inputs. No new proof, Gnark export, benchmark latency, minimum-RAM, mobile or AWS result is claimed.\n\nA distinct follow-up will examine occurrence frequencies for scalar translation. Given one key-only point sum S, the identity sum(s_i P_i)=cS+sum((s_i-c)P_i) can omit the most frequent scalar class rather than zero. Unlike opposite-value grouping, this could remove a large class-formation tree. This is unimplemented and has no performance result; input-dependent regrouping, key-sum setup, memory admission and full-prover costs must be included.\n\nAccepted primary remains historically 8.594267 ms and merge54 178.891799 ms. All eight supplied CPU 10× targets remain unmet. The unchanged [accepted CPU/Metal comparisons](../2026-10-25-grouping-module/artifacts/perf/report.md) remain authoritative.\n\n[Protocol](artifacts/experiment.json), [counts and closing audit](artifacts/results.json), [driver](artifacts/probe.rs), [workflow](artifacts/plan.json), [source/input pins](artifacts/input-pins.json).\n");fs::write(report.join("README.md"),s).unwrap();println!("CLOSED27queries 18solves 54fieldchecks {checks}integerchecks202pins; maxA/Bclassreduction{:.6}%",max*100.);
}
